(()=>{'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('ar-EG');
const euro='ج.م';
const uid=()=>globalThis.crypto?.randomUUID?.()||('s'+Date.now()+Math.random().toString(36).slice(2));
const api=async(url,opts={})=>{
 const res=await fetch(url,{credentials:'same-origin',cache:'no-store',...opts,headers:{'X-Requested-With':'HalabAdmin',...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})}});
 const json=await res.json().catch(()=>({}));
 if(!res.ok)throw Error(json.error||`خطأ ${res.status}`);
 return json;
};
let schedules=[],basketReport=null,backups=[],bulkSelected=new Set(),bulkFilter='',originalMenuForAdmin=null;
let menu=null,original='',dirty=false,active='overview',q='',recoQuery='',selectedCat='',orders=[],toastTimer,imageStatus=null,role='staff',username='',promotions={coupons:[],bundles:[],usage:{}},users=[],report=null,orderQuery='',soundEnabled=false,seenOrderIds=null,smartProduct='';
const tabs=[['overview','🏠','نظرة عامة'],['sections','📋','الأقسام'],['products','🍽️','الأصناف'],['recommendations','✨','العروض والمقترحات'],['extras','🧀','الإضافات والأحجام'],['promotions','🎟','الكوبونات والوجبات'],['pricing','📅','جدولة الأسعار'],['bulk','🧮','التعديل الجماعي'],['analytics','🛒','تحليل السلة'],['backups','💾','النسخ الاحتياطي'],['orders','📦','الطلبات'],['hours','🕒','العمل والتوصيل'],['reports','📊','تقارير المبيعات'],['customers','👥','العملاء'],['users','🔐','المستخدمون'],['appearance','🎨','شكل الموقع'],['settings','⚙️','الإعدادات']];
const managerPages=new Set(['overview','sections','products','recommendations','extras','promotions','hours','users','appearance','settings','pricing','bulk','backups']);
const allowedTab=t=>role==='admin'||(!managerPages.has(t)&&(role==='cashier'||t==='orders'));
async function loadExtras(){if(role==='admin'){promotions=await api('/api/admin/promotions');users=(await api('/api/admin/users')).users;schedules=(await api('/api/admin/pricing-schedules')).schedules;backups=(await api('/api/admin/backups')).backups;}if(role!=='staff'){report=await api('/api/admin/report');basketReport=await api('/api/admin/basket-analytics');}}
const csvCell=v=>{let t=String(v??'');if(/^[\s]*[=+@\-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};
const download=(name,text,type='text/csv;charset=utf-8')=>{const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);};
const csvExport=(rows,file)=>download(file,'\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));

const setDirty=v=>{dirty=v;$('#dirtyBanner').classList.toggle('hidden',!v);};
const changed=()=>{setDirty(true);render();};
const notice=text=>{const e=$('#toast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3500);};
const showError=e=>notice('⚠️ '+(e?.message||String(e)));
const confirmDirty=()=>!dirty||confirm('عندك تعديلات لم تُحفظ. هل تريد مغادرة الصفحة بدون حفظها؟');
const secItems=()=>menu.sections.flatMap((s,si)=>s.items.map((item,ii)=>({item,si,ii,section:s})));
const getSettings=()=>menu.settings||(menu.settings={});
const recoSettings=()=>{
 const s=getSettings();
 if(!Array.isArray(s.offers))s.offers=[];
 if(typeof s.offersEnabled!=='boolean')s.offersEnabled=true;
 if(typeof s.offersTitle!=='string')s.offersTitle='العروض';
 if(!s.upsell||typeof s.upsell!=='object'||Array.isArray(s.upsell))s.upsell={enabled:true,limit:3,items:['مياه','V كولا','اضافة كول سلو','ماكس كولا','علبة بطاطس بالجبنة'].filter(n=>secItems().some(x=>x.item.name===n))};
 if(!Array.isArray(s.upsell.items))s.upsell.items=[];
 if(typeof s.upsell.enabled!=='boolean')s.upsell.enabled=true;
 if(!Number.isInteger(s.upsell.limit)||s.upsell.limit<1||s.upsell.limit>6)s.upsell.limit=3;
 if(!s.upsell.byProduct||typeof s.upsell.byProduct!=='object')s.upsell.byProduct={};
 return s;
};
const recoName=x=>typeof x==='string'?x:String(x?.ref||'');
const recoList=kind=>kind==='offers'?recoSettings().offers:recoSettings().upsell.items;
const removeRecommendation=name=>{
 const s=recoSettings();s.offers=s.offers.filter(x=>recoName(x)!==name);
 s.upsell.items=s.upsell.items.filter(x=>x!==name);
 delete s.upsell.byProduct[name];for(const n of Object.keys(s.upsell.byProduct))s.upsell.byProduct[n]=s.upsell.byProduct[n].filter(x=>x!==name);
};
const renameRecommendation=(oldName,newName)=>{
 if(oldName===newName)return;
 const s=recoSettings();s.offers=s.offers.map(x=>recoName(x)===oldName?newName:x);
 s.upsell.items=s.upsell.items.map(x=>x===oldName?newName:x);
 if(Object.hasOwn(s.upsell.byProduct,oldName)){s.upsell.byProduct[newName]=s.upsell.byProduct[oldName];delete s.upsell.byProduct[oldName];}
 for(const name of Object.keys(s.upsell.byProduct))s.upsell.byProduct[name]=s.upsell.byProduct[name].map(x=>x===oldName?newName:x);
};
const view=(page)=>{if(!allowedTab(page))page='orders';active=page;$('#pageTitle').textContent=tabs.find(x=>x[0]===page)?.[2]||'لوحة التحكم';$('#sideNav').innerHTML=tabs.filter(([id])=>allowedTab(id)).map(([id,ico,name])=>`<button class="navlink ${active===id?'on':''}" data-tab="${id}"><span class="ico">${ico}</span>${name}</button>`).join('');for(const id of ['#saveTop','#saveMobile'])$(id).classList.toggle('hidden',role!=='admin');render();};
const safeSrc=s=>/^(https?:\/\/|\/assets\/)/i.test(s||'')?esc(s):'/assets/logo.webp';
const picture=(item,cl='mini-picture')=>`<img class="${cl}" src="${safeSrc(item.image||menu.logo)}" loading="lazy" alt="">`;
const renderOverview=()=>{
 const total=secItems(),unavailable=total.filter(x=>x.item.off).length,newOrders=orders.filter(x=>x.status==='new').length;
 return `<div class="stats"><div class="stat"><small>الأقسام</small><b>${fmt(menu.sections.length)}</b><span>أقسام المنيو</span></div><div class="stat"><small>الأصناف</small><b>${fmt(total.length)}</b><span>صنف في القائمة</span></div><div class="stat"><small>غير متوفر</small><b>${fmt(unavailable)}</b><span>يمكن تغيير التوفر</span></div><div class="stat"><small>طلبات جديدة</small><b>${fmt(newOrders)}</b><span>مسجلة في السيرفر</span></div></div>
 <div class="grid2"><div class="box"><div class="box-header"><h3>آخر الطلبات</h3><button class="btn small" data-tab="orders">عرض الكل ←</button></div>${orders.slice(0,5).map(o=>`<div class="entry"><div><strong>${esc(o.customer||'عميل')}</strong><small>${esc(o.id)} • ${when(o.createdAt)}</small></div><b>${fmt(o.total)} ${euro}</b></div>`).join('')||'<div class="empty">لا توجد طلبات مسجلة بعد</div>'}</div>
 <div class="box"><h3>حالة الموقع</h3><p class="panel-note">المنيو العام متصل بملف البيانات على السيرفر. عند الضغط على «حفظ» تظهر التعديلات للعملاء أثناء التحديث التالي (حوالي 20 ثانية).</p><p class="note">الطلبات المرسلة من الموقع يتم تسجيلها هنا إذا نجح اتصال العميل بالسيرفر. الفاتورة عبر واتساب تحتاج تأكيد المطعم.</p><a class="btn green" href="/" target="_blank" rel="noopener">↗ مشاهدة المنيو</a></div></div>
 <div class="box"><div class="box-header"><h3>الصور على الاستضافة</h3><button class="btn green" data-sync-images ${imageStatus?.running?'disabled':''}>↻ استعادة الصور الأصلية</button></div><p class="panel-note">الصور المحفوظة: <b>${imageStatus?fmt(imageStatus.cached):'—'}</b> / ${imageStatus?fmt(imageStatus.total):'—'} صورة. الصور غير المتاحة يظهر مكانها شعار المطعم، ويتم محاولة حفظها محليًا.</p>${imageStatus?.running?'<p class="note">جاري فحص الصور وتنزيل المتاح منها...</p>':''}<p class="note">استعادة الصور تتطلب اتصال الاستضافة بالسيرفر الذي يحتوي على الصور الأصلية.</p></div>`;
};
const renderSections=()=>`<div class="box"><div class="box-header"><div><h3>أقسام المنيو</h3><div class="note">رتّب الأقسام، وعدّل اسم القسم أو أضف أقساماً جديدة.</div></div><button class="btn primary" data-add-section>+ إضافة قسم</button></div>
 <div class="table-wrap"><table><thead><tr><th>الترتيب</th><th>اسم القسم</th><th>عدد الأصناف</th><th>العمليات</th></tr></thead><tbody>${menu.sections.map((s,i)=>`<tr><td><button class="btn small ghost" data-move-section="${i}" data-step="-1" ${i===0?'disabled':''}>↑</button> <button class="btn small ghost" data-move-section="${i}" data-step="1" ${i===menu.sections.length-1?'disabled':''}>↓</button></td><td><b>${esc(s.name)}</b> ${s.hidden?'<span class="tag off">مخفي</span>':s.disabled?'<span class="tag off">متوقف</span>':''}</td><td>${s.items.length}</td><td><div class="actions-cell"><button class="btn small" data-edit-section="${i}">تعديل</button><button class="btn small ghost" data-toggle-section="${i}">${s.disabled?'تشغيل القسم':'إيقاف القسم'}</button><button class="btn small ghost" data-hide-section="${i}">${s.hidden?'إظهار':'إخفاء'}</button><button class="btn small" data-go-section="${i}">الأصناف</button><button class="btn small danger" data-del-section="${i}">حذف</button></div></td></tr>`).join('')}</tbody></table></div></div>`;
const renderProducts=()=>{
 const candidates=secItems().filter(x=>(selectedCat===''||String(x.si)===selectedCat)&&(!q||(`${x.item.name} ${x.item.description||''} ${x.section.name}`).toLowerCase().includes(q.toLowerCase())));
 return `<div class="box"><div class="box-header"><div><h3>إدارة الأصناف</h3><p class="note">اسم الصنف يجب ألا يتكرر؛ البحث والتغيير متاحان لجميع الأصناف.</p></div><button class="btn primary" data-add-item>+ إضافة صنف</button></div><div class="searchrow"><input class="edit-input" id="findItems" placeholder="بحث باسم الصنف..." value="${esc(q)}"><select id="catFilter"><option value="">كل الأقسام</option>${menu.sections.map((s,i)=>`<option value="${i}" ${selectedCat===String(i)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><p class="note">النتائج: ${fmt(candidates.length)}</p>
 <div class="table-wrap"><table><thead><tr><th>الصنف</th><th>القسم</th><th>السعر</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>${candidates.map(({item,si,ii,section})=>`<tr><td>${picture(item)} <b>${esc(item.name)}</b></td><td>${esc(section.name)}</td><td>${fmt(item.price)} ${euro}</td><td><span class="tag ${item.off?'off':''}">${item.hidden?'مخفي':item.off?'نفد مؤقتاً':'متوفر'}</span></td><td><div class="actions-cell"><button class="btn small" data-edit-item="${si}:${ii}">تعديل</button><button class="btn small ghost" data-toggle-item="${si}:${ii}">${item.off?'تفعيل':'نفد مؤقتاً'}</button><button class="btn small ghost" data-hide-item="${si}:${ii}">${item.hidden?'إظهار':'إخفاء'}</button><button class="btn small danger" data-del-item="${si}:${ii}">حذف</button></div></td></tr>`).join('')}</tbody></table></div>${candidates.length?'':'<div class="empty">لا توجد أصناف مطابقة</div>'}</div>`;
};
const renderRecommendations=()=>{
 const s=recoSettings(),all=secItems();
 const renderSelected=(kind)=>{
  const sel=recoList(kind);
  return sel.map((entry,i)=>{
   const name=recoName(entry),found=all.find(x=>x.item.name===name),it=found?.item;
   return `<div class="entry"><div style="display:flex;align-items:center;gap:10px;min-width:0">${it?picture(it):'<span>🖼️</span>'}<div><strong>${esc(name)}</strong><small>${it?esc(found.section.name)+' • '+fmt(it.price)+' ج.م': 'تم حذف الصنف من المنيو'} ${it?.off?' • غير متوفر':''}</small></div></div><div class="actions"><button class="btn small ghost" data-rec-move="${kind}:${i}" data-step="-1" ${i===0?'disabled':''} title="تقديم">↑</button><button class="btn small ghost" data-rec-move="${kind}:${i}" data-step="1" ${i===sel.length-1?'disabled':''} title="تأخير">↓</button><button class="btn small danger" data-rec-remove="${kind}:${i}">حذف</button></div></div>`;
  }).join('')||'<div class="empty">مفيش أصناف مختارة. اختار من القائمة تحت.</div>';
 };
 const found=all.filter(x=>!recoQuery||`${x.item.name} ${x.section.name}`.toLowerCase().includes(recoQuery.toLowerCase())).slice(0,60);
 return `<div class="panel-note">اختار الأصناف اللي عايز تبرزها في بداية المنيو وفي «كمّل وجبتك» داخل السلة. تقدر تختار من أي قسم، وترتّبها وتحذفها. الصنف غير المتوفر مش هيظهر للعملاء. <b>بعد كل تعديل اضغط حفظ جميع التغييرات.</b></div>
 <div class="grid2"><div class="box"><div class="box-header"><h3>⭐ العروض والمقترحات في أول المنيو (${s.offers.length})</h3></div><label class="check"><input type="checkbox" id="offersEnabled" ${s.offersEnabled?'checked':''}> إظهار القسم في الصفحة الرئيسية</label><label class="field"><span>عنوان القسم الذي يظهر للعملاء</span><input id="offersTitle" value="${esc(s.offersTitle)}" maxlength="60" placeholder="العروض"></label>${renderSelected('offers')}</div>
 <div class="box"><div class="box-header"><h3>🍟 كمّل وجبتك (${s.upsell.items.length})</h3></div><label class="check"><input type="checkbox" id="upsellEnabled" ${s.upsell.enabled?'checked':''}> إظهار «كمّل وجبتك» في سلة العملاء</label><label class="field"><span>أقصى عدد مقترحات في السلة (الأصناف في السلة أو غير المتوفرة تُستبعد تلقائياً)</span><select id="upsellLimit">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${s.upsell.limit===n?'selected':''}>${n} ${n===1?'صنف':'أصناف'}</option>`).join('')}</select></label>${renderSelected('upsell')}</div></div>
 <div class="box"><h3>🎯 اقتراحات مخصصة لكل صنف</h3><p class="note">اختار الصنف الأساسي ثم أضف له الأصناف المقترحة. يظهر ترتيبك أولاً عند وجوده في السلة ثم المقترحات العامة. حذف جميع الاقتراحات المخصصة يرجع للوضع العام.</p>
 <select id="smartProduct"><option value="">اختر الصنف الأساسي</option>${all.map(x=>`<option value="${esc(x.item.name)}" ${smartProduct===x.item.name?'selected':''}>${esc(x.item.name)} — ${esc(x.section.name)}</option>`).join('')}</select>
 ${smartProduct?`<h3 style="margin-top:15px">مقترحات: ${esc(smartProduct)}</h3>${(s.upsell.byProduct[smartProduct]||[]).map((name,i,arr)=>`<div class="entry"><strong>${esc(name)}</strong><div class="actions"><button class="btn small" data-smart-move="${i}" data-step="-1" ${i===0?'disabled':''}>↑</button><button class="btn small" data-smart-move="${i}" data-step="1" ${i===arr.length-1?'disabled':''}>↓</button><button class="btn small danger" data-smart-remove="${i}">حذف</button></div></div>`).join('')}<select id="smartSuggestion"><option value="">اختر صنف تضيفه</option>${all.filter(x=>x.item.name!==smartProduct&&!((s.upsell.byProduct[smartProduct])||[]).includes(x.item.name)).map(x=>`<option value="${esc(x.item.name)}">${esc(x.item.name)}</option>`).join('')}</select><button class="btn primary" data-smart-add>+ إضافة الاقتراح</button>`:''}</div>
 <div class="box"><h3>➕ اختار أصناف لعرضها</h3><p class="note">ابحث عن أي صنف وأضفه للقسم المناسب. يمكن إضافة نفس الصنف للعروض و«كمّل وجبتك».</p><input class="edit-input" id="recoSearch" placeholder="ابحث باسم الصنف أو القسم..." value="${esc(recoQuery)}"><p class="note">عرض ${found.length} من نتائج البحث. السعر بيتحدث تلقائياً من المنيو.</p>
 <div class="table-wrap"><table><thead><tr><th>الصنف</th><th>السعر والحالة</th><th>أضف إلى</th></tr></thead><tbody>${found.map(({item,section})=>`<tr><td>${picture(item)}<b>${esc(item.name)}</b><div class="note">${esc(section.name)}</div></td><td>${fmt(item.price)} ج.م ${item.off?'<span class="tag off">غير متوفر</span>':''}</td><td><div class="actions-cell"><button class="btn small" data-rec-add="offers" data-name="${esc(item.name)}" ${s.offers.some(x=>recoName(x)===item.name)?'disabled':''}>⭐ العروض</button><button class="btn small green" data-rec-add="upsell" data-name="${esc(item.name)}" ${s.upsell.items.includes(item.name)?'disabled':''}>🍟 كمّل وجبتك</button></div></td></tr>`).join('')}</tbody></table></div>${!found.length?'<div class="empty">لا توجد نتائج مطابقة</div>':''}</div>`;
};
const statuses={new:'جديد',accepted:'تم القبول',preparing:'جاري التحضير',onway:'خرج للتوصيل',delivered:'مكتمل',cancelled:'ملغي'};
const when=s=>{try{return new Date(s).toLocaleString('ar-EG',{timeZone:'Africa/Cairo',dateStyle:'short',timeStyle:'short'});}catch{return esc(s)}};
const renderOrders=()=>`<div class="box"><div class="box-header"><div><h3>الطلبات الواردة</h3><p class="note">بيانات محفوظة على سيرفر الموقع. لا تعتبر الطلب مؤكدًا إلا بعد التواصل مع العميل.</p></div><div class="actions"><button class="btn" data-refresh-orders>↻ تحديث</button><button class="btn ${soundEnabled?'green':'ghost'}" data-sound>${soundEnabled?'🔔 التنبيه مفعل':'🔕 تفعيل صوت الطلبات'}</button><button class="btn ghost" data-export-orders>↓ تنزيل نسخة JSON</button></div></div><input id="orderSearch" class="edit-input" placeholder="ابحث برقم الطلب أو اسم العميل" value="${esc(orderQuery)}">${orders.filter(o=>!orderQuery||(`${o.id} ${o.customer}`).toLowerCase().includes(orderQuery.toLowerCase())).map(o=>`<div class="order"><div class="order-head"><div><h3>${esc(o.customer||'عميل بدون اسم')} <span class="tag">${esc(o.id)}</span></h3><p>${when(o.createdAt)} • ${o.type==='delivery'?'توصيل':o.type==='dine'?'داخل المطعم':'استلام'}${o.zone?' • '+esc(o.zone):''}</p></div><div><b>${fmt(o.total)} ${euro}</b></div></div><ul>${o.items.map(i=>`<li>${esc(i.name)} ${i.weight?'('+esc(i.weight)+')':''} ${(i.addons||[]).length?' + '+esc(i.addons.map(x=>x.name).join('، ')):''} × ${fmt(i.quantity)} — ${fmt(i.unitPrice*i.quantity)} ${euro}</li>`).join('')}</ul><div class="note order-details">${o.address?'العنوان: '+esc(o.address)+'\n':''}${o.notes?'ملاحظات: '+esc(o.notes)+'\n':''}خصم: ${fmt(o.discount||0)} ${euro} | رسوم التوصيل: ${fmt(o.deliveryFee)} ${euro} ${o.couponCode?' | كوبون: '+esc(o.couponCode):''}</div><div class="order-footer"><span class="label">الحالة:</span><select data-order-status="${esc(o.id)}">${Object.entries(statuses).map(([id,title])=>`<option value="${id}" ${o.status===id?'selected':''}>${title}</option>`).join('')}</select></div></div>`).join('')||'<div class="empty">لا يوجد طلبات حتى الآن</div>'}</div>`;
const field=(id,label,val,type='text')=>`<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(val??'')}"></label>`;
const settings=()=>{const c=menu.contact||{},s=menu.settings||{};return `<div class="grid2"><div class="box"><h3>بيانات المطعم</h3><form id="settingsForm">${field('setName','اسم المطعم',menu.name)}${field('setPhone','هاتف الطلبات',c.phone||'')}${field('setWhats','رقم واتساب',c.whatsapp||'')}${field('setFacebook','رابط فيسبوك',c.facebook||'')}${field('setHotline','الخط الساخن',s.hotline||'17665')}${field('setSubtitle','سطر أسفل اسم المطعم',s.heroSubtitle||'قائمة الطعام والأسعار')}${field('setLogo','رابط الشعار',menu.logo||'')}${field('setCover','رابط صورة الغلاف',menu.cover||'')}<label class="check"><input id="setOrders" type="checkbox" ${c.orders!==false?'checked':''}> السماح بطلبات العملاء</label><button class="btn primary" type="submit">تطبيق في المنيو (ثم اضغط حفظ)</button></form></div>
 <div class="box"><h3>مناطق ورسوم التوصيل</h3><p class="note">أدخل منطقة ورسومها في كل سطر بالشكل: اسم المنطقة | رسوم التوصيل. استخدم أرقام حقيقية فقط.</p><textarea id="zonesText" class="edit-input" rows="9" style="resize:vertical" placeholder="العبور | 35">${esc((s.zones||[]).map(z=>`${z.name} | ${z.fee}`).join('\n'))}</textarea>${field('setFree','حد التوصيل المجاني بالجنيه (0 = إيقاف)',s.freeDeliveryThreshold||0,'number')}<button class="btn green" data-save-zones>تطبيق رسوم التوصيل (ثم حفظ)</button><div class="sep"></div><h3>صور المنيو</h3><p class="note">عند تعديل صنف يمكنك اختيار صورة JPG أو PNG أو WEBP وسيتم رفعها إلى السيرفر.</p><p class="note">احتفظ بنسخة احتياطية من ملفات البيانات قبل نقل أو إعادة تثبيت الاستضافة.</p></div></div>`;};

const groupList=()=>getSettings().addonGroups||(getSettings().addonGroups=[]);
const renderExtras=()=>`<div class="panel-note">أضف مجموعة مثل «الصوص» أو «الجبنة» وحدد الاختيار إجباري أو اختياري، وبعدها اربطها بالصنف من زر تعديل الصنف. الأحجام وأسعارها تُعدّل من شاشة الأصناف.</div><div class="box"><div class="box-header"><h3>🧀 مجموعات الإضافات (${groupList().length})</h3><button class="btn primary" data-group-edit="new">+ مجموعة إضافات</button></div>${groupList().map((g,i)=>`<div class="entry"><div><strong>${esc(g.name)}</strong><small>${g.required?'إجباري':'اختياري'} · ${g.options.map(o=>`${o.name} (${fmt(o.price)} ج)`).map(esc).join('، ')} · مرتبط بـ ${secItems().filter(x=>(x.item.addonGroups||[]).includes(g.id)).length} صنف</small></div><div class="actions"><button class="btn small" data-group-edit="${i}">تعديل</button><button class="btn small danger" data-group-delete="${i}">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد إضافات</div>'}</div>`;
const renderPromotions=()=>`<div class="panel-note">الكوبونات محفوظة على السيرفر فقط؛ لا تظهر أكوادها للزائر. خصم عرض الوجبة يُطبّق تلقائياً عند وجود كل الأصناف المطلوبة، ويمكن إضافة كوبون بعده. عند تعدد عروض الوجبة يختار النظام أكبر خصم.</div><div class="grid2"><div class="box"><div class="box-header"><h3>🎟 كوبونات الخصم</h3><button class="btn primary" data-coupon-edit="new">+ كوبون</button></div>${promotions.coupons.map((c,i)=>`<div class="entry"><div><strong>${esc(c.code)} ${!c.enabled?'(معطل)':''}</strong><small>${c.type==='percent'?c.value+'%':fmt(c.value)+' ج'} · استخدام ${promotions.usage?.[c.code]||0} من ${c.maxUses||'غير محدود'} · ينتهي ${esc(c.expires?c.expires.slice(0,10):'بدون تاريخ')}</small></div><div class="actions"><button class="btn small" data-coupon-edit="${i}">تعديل</button><button class="btn small danger" data-coupon-delete="${i}">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد كوبونات</div>'}</div><div class="box"><div class="box-header"><h3>🍱 عروض الوجبات</h3><button class="btn primary" data-bundle-edit="new">+ عرض وجبة</button></div>${promotions.bundles.map((b,i)=>`<div class="entry"><div><strong>${esc(b.title)} ${!b.enabled?'(معطل)':''}</strong><small>${esc(b.items.join(' + '))} · خصم ${b.type==='percent'?b.value+'%':fmt(b.value)+' ج'}</small></div><div class="actions"><button class="btn small" data-bundle-edit="${i}">تعديل</button><button class="btn small danger" data-bundle-delete="${i}">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد عروض وجبات</div>'}</div></div>`;
const days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
const renderHours=()=>{const s=getSettings(),h=s.schedule||{enabled:false,days:{}};return `<div class="grid2"><div class="box"><h3>🕒 مواعيد استقبال الطلبات بتوقيت القاهرة</h3><p class="note">اختر أيام العمل؛ يمكنك وضع الإغلاق بعد منتصف الليل مثل 12:00 إلى 02:00. إيقاف الجدول يعني استقبال الطلبات دائماً ما دام زر استقبال الطلبات مفعلًا.</p><label class="check"><input id="scheduleOn" type="checkbox" ${h.enabled?'checked':''}> تفعيل الإغلاق التلقائي حسب المواعيد</label>${days.map((d,i)=>{const x=h.days?.[i];return `<div class="entry"><label class="check"><input type="checkbox" data-workday="${i}" ${x?'checked':''}>${d}</label><input class="edit-input" style="width:110px" type="time" data-open="${i}" value="${esc(x?.open||'10:00')}"><input class="edit-input" style="width:110px" type="time" data-close="${i}" value="${esc(x?.close||'23:00')}"></div>`}).join('')}<button class="btn primary" data-save-hours>تطبيق مواعيد العمل (ثم حفظ)</button></div><div class="box"><h3>🚚 مناطق التوصيل وحد الطلب</h3>${field('minimumOrder','الحد الأدنى لقيمة الطلب بالجنيه (0 = بدون حد)',s.minimumOrder||0,'number')}<p class="note">اكتب المنطقة | رسوم التوصيل، كل منطقة بسطر</p><textarea class="edit-input" id="workZones" rows="10">${esc((s.zones||[]).map(z=>z.name+' | '+z.fee).join('\n'))}</textarea>${field('workFree','التوصيل المجاني عند مبلغ (0 = إيقاف)',s.freeDeliveryThreshold||0,'number')}<button class="btn primary" data-save-delivery>تطبيق التوصيل (ثم حفظ)</button></div></div>`};
const renderReports=()=>{if(!report)return '<div class="empty">جاري تحميل التقرير</div>';const {summary,daily,monthly,items}=report;return `<div class="stats"><div class="stat"><small>إجمالي الطلبات</small><b>${fmt(summary.orders)}</b></div><div class="stat"><small>الطلبات الملغية</small><b>${fmt(summary.cancelled)}</b></div><div class="stat"><small>الإيراد (جنيه)</small><b>${fmt(summary.revenue)}</b></div><div class="stat"><small>الطلبات المحتسبة</small><b>${fmt(report.orders.filter(o=>!['new','cancelled'].includes(o.status)).length)}</b></div></div><div class="box"><div class="actions"><button class="btn green" data-export-sales>↓ تحميل Excel (.xlsx)</button><button class="btn" data-refresh-reports>↻ تحديث التقارير</button></div><p class="note">الإيرادات للطلبات المقبولة أو الجارية أو المكتملة، ولا تُحسب الطلبات الجديدة أو الملغية. التقارير حسب التاريخ المسجل UTC.</p></div><div class="grid2"><div class="box"><h3>المبيعات اليومية</h3>${Object.entries(daily).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,31).map(([d,v])=>`<div class="entry"><strong>${d}</strong><b>${fmt(v)} ج</b></div>`).join('')||'لا يوجد'}</div><div class="box"><h3>المبيعات الشهرية</h3>${Object.entries(monthly).sort((a,b)=>b[0].localeCompare(a[0])).map(([d,v])=>`<div class="entry"><strong>${d}</strong><b>${fmt(v)} ج</b></div>`).join('')||'لا يوجد'}<div class="sep"></div><h3>الأكثر مبيعاً (بالعدد)</h3>${Object.entries(items).sort((a,b)=>b[1]-a[1]).slice(0,15).map(([n,v])=>`<div class="entry"><strong>${esc(n)}</strong><b>${fmt(v)}</b></div>`).join('')||'لا يوجد'}</div></div>`};
const customerGroups=()=>{const r=new Map();for(const o of orders){const key=[(o.customer||'بدون اسم').trim(),(o.address||'').trim()].join('|');if(!r.has(key))r.set(key,{name:o.customer||'بدون اسم',address:o.address||'',orders:[],spent:0});const c=r.get(key);c.orders.push(o);if(!['new','cancelled'].includes(o.status))c.spent+=o.total;}return [...r.values()].sort((a,b)=>b.orders.length-a.orders.length);};
const renderCustomers=()=>`<div class="panel-note">السجل مبني على الاسم والعنوان المكتوبين في الطلبات، وليس حسابات عملاء موثقة. أسماء متشابهة قد تشير لأشخاص مختلفين؛ البيانات تظهر للمصرح لهم فقط.</div><div class="box"><h3>👥 العملاء (${customerGroups().length})</h3>${customerGroups().map(c=>`<details class="entry" style="display:block"><summary><strong>${esc(c.name)}</strong> · ${c.orders.length} طلب · ${fmt(c.spent)} ج</summary><p class="note">${esc(c.address)}</p>${c.orders.map(o=>`<div class="entry"><span>${esc(o.id)} · ${when(o.createdAt)} · ${esc(statuses[o.status]||o.status)}</span><b>${fmt(o.total)} ج</b></div>`).join('')}</details>`).join('')||'<div class="empty">لا يوجد طلبات</div>'}</div>`;
const renderUsers=()=>`<div class="panel-note">المدير يعدّل الموقع والمستخدمين، الكاشير يتابع الطلبات والتقارير والعملاء، والموظف يتابع الطلبات فقط. لا تُعرض كلمات المرور بعد الحفظ.</div><div class="box"><div class="box-header"><h3>حسابات الموظفين</h3><button class="btn primary" data-user-add>+ حساب جديد</button></div>${users.map(u=>`<div class="entry"><div><strong>${esc(u.username)}</strong><small>${({admin:'مدير',cashier:'كاشير',staff:'موظف'})[u.role]}</small></div><div class="actions"><button class="btn small" data-user-edit="${esc(u.id)}">صلاحيات / كلمة سر</button><button class="btn small danger" data-user-delete="${esc(u.id)}" ${u.username===username?'disabled':''}>حذف</button></div></div>`).join('')}</div>`;
const renderAppearance=()=>{const s=getSettings(),t=s.theme||{};return `<div class="grid2"><div class="box"><h3>🎨 الهوية والألوان</h3><form id="appearanceForm">${field('styleTitle','عنوان البانر الرئيسي',t.title||'')}${field('styleSub','الوصف أسفل العنوان',s.heroSubtitle||'قائمة الطعام والأسعار')}${field('stylePrimary','اللون الأساسي (HEX)',t.primary||'#b18b4b')}${field('styleAccent','لون التمييز (HEX)',t.accent||'#ddba75')}${field('styleLogo','رابط اللوجو',menu.logo||'')}${field('styleCover','رابط الغلاف',menu.cover||'')}<label class="field"><span>رفع لوجو من الجهاز</span><input type="file" id="styleLogoFile" accept="image/png,image/jpeg,image/webp"></label><label class="field"><span>رفع صورة الغلاف</span><input type="file" id="styleCoverFile" accept="image/png,image/jpeg,image/webp"></label><button class="btn primary" type="submit">تطبيق التصميم (ثم حفظ)</button></form></div><div class="box"><h3>🖼 بانرات إضافية فوق القائمة</h3><p class="note">كل سطر: عنوان | رابط صورة (HTTPS أو صورة مرفوعة). تُعرض بنفس الترتيب.</p><textarea id="bannersText" class="edit-input" rows="9" placeholder="وجبات جديدة | https://...">${esc((s.banners||[]).map(b=>b.title+' | '+b.image).join('\n'))}</textarea><button class="btn green" data-save-banners>تطبيق البانرات (ثم حفظ)</button><p class="note">إخفاء وترتيب الأقسام متاح من تبويب الأقسام.</p></div></div>`};
const parsePriceRows=(str)=>str.split(/\n/).map(v=>v.trim()).filter(Boolean).map(row=>{const p=row.split('|').map(x=>x.trim());if(p.length!==2||!p[0]||!Number.isFinite(Number(p[1]))||Number(p[1])<0)throw Error('صيغة الاسم | السعر غير صحيحة: '+row);return {name:p[0],price:Number(p[1])};});
async function savePromotions(){await api('/api/admin/promotions',{method:'PUT',body:JSON.stringify({coupons:promotions.coupons,bundles:promotions.bundles})});promotions=await api('/api/admin/promotions');render();notice('تم حفظ العروض والكوبونات على السيرفر');}
function groupModal(index){const g=index===null?{id:uid(),name:'',required:false,options:[]}:groupList()[index];modal(`<h2>مجموعة إضافات</h2><form id="groupForm">${field('gName','اسم المجموعة',g.name)}<label class="check"><input type="checkbox" id="gRequired" ${g.required?'checked':''}> الاختيار إجباري</label><label class="field"><span>الاختيارات (الاسم | السعر في كل سطر)</span><textarea id="gOptions" required>${esc(g.options.map(o=>o.name+' | '+o.price).join('\n'))}</textarea></label><div class="modal-tools"><button class="btn ghost" type="button" data-close>إلغاء</button><button class="btn primary">تطبيق ثم حفظ المنيو</button></div></form>`);$('#groupForm').onsubmit=e=>{e.preventDefault();try{const options=parsePriceRows($('#gOptions').value),name=$('#gName').value.trim();if(!name||!options.length)throw Error('اسم المجموعة واختياراتها مطلوبة');const obj={id:g.id,name,required:$('#gRequired').checked,options};if(index===null)groupList().push(obj);else groupList()[index]=obj;hideModal();changed();}catch(err){showError(err);}};}
function couponModal(index){const c=index===null?{code:'',type:'percent',value:10,maxUses:0,minSubtotal:0,enabled:true,expires:''}:promotions.coupons[index];modal(`<h2>كوبون خصم</h2><form id="couponForm">${field('couponCode','كود الكوبون (English)',c.code)}<label class="field"><span>نوع الخصم</span><select id="couponType"><option value="percent" ${c.type==='percent'?'selected':''}>نسبة %</option><option value="fixed" ${c.type==='fixed'?'selected':''}>مبلغ جنيه</option></select></label>${field('couponValue','الخصم',c.value,'number')}${field('couponMax','الحد الأقصى للاستخدام (0 = غير محدود)',c.maxUses,'number')}${field('couponMin','أقل إجمالي لاستخدام الكوبون',c.minSubtotal,'number')}${field('couponExpire','تاريخ آخر يوم (اختياري)',c.expires?c.expires.slice(0,10):'','date')}<label class="check"><input id="couponEnabled" type="checkbox" ${c.enabled?'checked':''}>مفعل</label><div class="modal-tools"><button type="button" class="btn ghost" data-close>إلغاء</button><button class="btn primary">حفظ الكوبون</button></div></form>`);$('#couponForm').onsubmit=async e=>{e.preventDefault();const obj={code:$('#couponCode').value.trim().toUpperCase(),type:$('#couponType').value,value:Number($('#couponValue').value),maxUses:Number($('#couponMax').value),minSubtotal:Number($('#couponMin').value),enabled:$('#couponEnabled').checked,expires:$('#couponExpire').value?new Date($('#couponExpire').value+'T23:59:59').toISOString():''};const old=[...promotions.coupons];try{if(index===null)promotions.coupons.push(obj);else promotions.coupons[index]=obj;await savePromotions();hideModal();}catch(err){promotions.coupons=old;showError(err);}};}
function bundleModal(index){const b=index===null?{id:uid(),title:'',items:[],type:'fixed',value:20,enabled:true}:promotions.bundles[index];modal(`<h2>عرض وجبة</h2><form id="bundleForm">${field('bundleTitle','اسم العرض',b.title)}<label class="field"><span>الأصناف المطلوبة (Ctrl أو Shift لتحديد أكثر من صنف)</span><select id="bundleItems" multiple size="10">${secItems().map(({item})=>`<option value="${esc(item.name)}" ${b.items.includes(item.name)?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><label class="field"><span>الخصم</span><select id="bundleType"><option value="percent" ${b.type==='percent'?'selected':''}>نسبة %</option><option value="fixed" ${b.type==='fixed'?'selected':''}>مبلغ</option></select></label>${field('bundleValue','قيمة الخصم',b.value,'number')}<label class="check"><input type="checkbox" id="bundleEnabled" ${b.enabled?'checked':''}>مفعل</label><div class="modal-tools"><button type="button" class="btn ghost" data-close>إلغاء</button><button class="btn primary">حفظ عرض الوجبة</button></div></form>`);$('#bundleForm').onsubmit=async e=>{e.preventDefault();const obj={id:b.id,title:$('#bundleTitle').value.trim(),items:[...$('#bundleItems').selectedOptions].map(x=>x.value),type:$('#bundleType').value,value:Number($('#bundleValue').value),enabled:$('#bundleEnabled').checked};const old=[...promotions.bundles];try{if(index===null)promotions.bundles.push(obj);else promotions.bundles[index]=obj;await savePromotions();hideModal();}catch(err){promotions.bundles=old;showError(err);}};}
function userModal(id){const u=users.find(x=>x.id===id);modal(`<h2>${u?'تعديل حساب '+esc(u.username):'حساب موظف جديد'}</h2><form id="userForm">${!u?field('userName','اسم المستخدم بالإنجليزية',''):''}<label class="field"><span>الصلاحية</span><select id="userRole">${[['admin','مدير'],['cashier','كاشير'],['staff','موظف']].map(([k,n])=>`<option value="${k}" ${u?.role===k?'selected':''}>${n}</option>`).join('')}</select></label>${field('userPass',u?'كلمة مرور جديدة (فارغة = بدون تغيير)':'كلمة المرور (12 حرفاً على الأقل)','', 'password')}<div class="modal-tools"><button class="btn ghost" type="button" data-close>إلغاء</button><button class="btn primary">حفظ</button></div></form>`);$('#userForm').onsubmit=async e=>{e.preventDefault();const body={role:$('#userRole').value};if(!u){body.username=$('#userName').value;body.password=$('#userPass').value;}else if($('#userPass').value)body.password=$('#userPass').value;try{await api('/api/admin/users'+(u?'/'+u.id:''),{method:u?'PATCH':'POST',body:JSON.stringify(body)});users=(await api('/api/admin/users')).users;hideModal();render();notice('تم حفظ المستخدم');}catch(err){showError(err);}};}
async function uploadFile(file){if(!file)return null;if(file.size>4_000_000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('الصورة يجب أن تكون PNG/JPG/WEBP وأقل من 4MB');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('لم تُقرأ الصورة'));r.readAsDataURL(file);});return (await api('/api/admin/upload',{method:'POST',body:JSON.stringify({data})})).url;}


// V5 ADMIN MODULES
const scheduleLabel=x=>x.type==='price'?'سعر ثابت':x.type==='percent_off'?'خصم نسبة %':'خصم مبلغ جنيه';
const cDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).reduce((a,b)=>(a[b.type]=b.value,a),{});
const cairoNow=()=>{const p=cDate();return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;};
const scheduleState=x=>{const now=cairoNow();if(!x.enabled)return 'متوقف';if(now<x.startAt)return 'قادم';if(now>=x.endAt)return 'انتهى';return 'فعّال الآن';};
const renderPricing=()=>`<div class="panel-note">الأسعار المجدولة تعمل تلقائياً بتوقيت القاهرة، وتُحسب على السيرفر عند فتح المنيو وتسجيل الطلب. السعر الأصلي لا يتغير. عند تعارض الجداول يسبق الصنفُ القسمَ، والأحدث بدايةً يسبق الأقدم. اختر صنفاً محدداً للسعر الثابت، أو خصماً على صنف أو قسم. تحديث المنيو للعميل كل 20 ثانية.</div>
<div class="box"><div class="box-header"><div><h3>📅 جداول الأسعار والعروض (${schedules.length})</h3><p class="note">السيرفر يطبق التغيير خلال نافذة البداية والنهاية حتى لو لوحة الإدارة مغلقة.</p></div><div class="actions"><button class="btn primary" data-schedule-edit="new">+ جدول جديد</button><button class="btn ghost" data-schedule-refresh>↻ تحديث</button></div></div>
${schedules.map((x,i)=>`<div class="entry"><div><strong>${esc(x.target)} ${x.variant?' · '+esc(x.variant):''} <span class="tag ${scheduleState(x)==='فعّال الآن'?'':'off'}">${scheduleState(x)}</span></strong><small>${x.scope==='section'?'قسم':'صنف'} · ${scheduleLabel(x)}: ${fmt(x.value)}${x.type==='percent_off'?'%':' ج.م'}<br>من ${esc(x.startAt.replace('T',' '))} إلى ${esc(x.endAt.replace('T',' '))} بتوقيت القاهرة</small></div><div class="actions"><button class="btn small" data-schedule-edit="${i}">تعديل</button><button class="btn small danger" data-schedule-delete="${i}">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد أسعار مجدولة حتى الآن</div>'}</div>`;
const renderBulk=()=>{const selection=secItems().filter(x=>!bulkFilter||x.section.name===bulkFilter);return `<div class="panel-note">هذه العملية تغيّر الأسعار الأساسية فوراً (بما فيها أسعار الأحجام)، ولا تغيّر جداول الخصم المستقبلية. اختر أصنافاً يدوياً؛ إذا لم تحدد أي صنف سيتم تعديل <b>القسم المختار بالكامل</b>. يتم حساب التعديل وحفظه مرة واحدة على السيرفر.</div>
<div class="grid2"><div class="box"><h3>🧮 تعديل جماعي</h3><label class="field"><span>القسم المراد تعديله (إذا لم تحدد أصنافاً)</span><select id="bulkScope"><option value="">— اختر القسم —</option>${menu.sections.map(s=>`<option value="${esc(s.name)}" ${bulkFilter===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="field"><span>العملية</span><select id="bulkAction"><option value="raise_percent">تغيير السعر بالنسبة المئوية</option><option value="availability">تغيير حالة التوفر</option></select></label><label class="field"><span>تغيير السعر بالنسبة % (مثال: 10 زيادة، -5 تخفيض)</span><input type="number" step="0.01" min="-90" max="500" id="bulkPercent" value="10"></label><label class="field"><span>حالة التوفر (عند اختيار عملية التوفر)</span><select id="bulkState"><option value="off">نفد مؤقتاً</option><option value="hidden">إخفاء</option><option value="available">إظهار ومتوفر</option></select></label><button class="btn primary" data-bulk-apply>تأكيد وتنفيذ التعديل الجماعي</button><p class="note">سيتم تحديث الأسعار على الموقع بعد الحفظ. لا يمكن التراجع إلا باستعادة نسخة احتياطية، لذلك خذ نسخة أولاً.</p></div>
<div class="box"><div class="box-header"><h3>اختيار الأصناف (${bulkSelected.size} محدد)</h3><div class="actions"><button class="btn small ghost" data-bulk-select>تحديد المعروض</button><button class="btn small ghost" data-bulk-clear>إلغاء التحديد</button></div></div><p class="note">تحديد أصناف هنا له الأولوية على القسم، حتى لو اخترت قسماً آخر. اعرض أصناف القسم من القائمة أعلاه.</p><div style="max-height:440px;overflow-y:auto">${selection.map(x=>`<label class="check" style="border-bottom:1px solid var(--line)"><input type="checkbox" data-bulk-item="${esc(x.item.name)}" ${bulkSelected.has(x.item.name)?'checked':''}><span>${esc(x.item.name)} · ${fmt(x.item.price)} ج.م <small class="muted">(${esc(x.section.name)})</small></span></label>`).join('')}</div></div></div>`;};
const renderBasketAnalytics=()=>{if(!basketReport)return '<div class="empty">لا توجد بيانات تحليل</div>';const r=basketReport;return `<div class="panel-note">الأرقام تخص الطلبات غير الجديدة وغير الملغاة فقط. «من كمّل وجبتك» تعني أن العميل أضاف الصنف بالضغط على الاقتراح؛ هذا ارتباط مسجل وليس إثباتاً أن الاقتراح تسبب وحده في الشراء. الطلبات قبل V5 لا تحتوي على تتبع لهذه الإضافة.</div>
<div class="stats"><div class="stat"><small>طلبات ضمن التحليل</small><b>${fmt(r.count)}</b></div><div class="stat"><small>طلبات بها اقتراح مُشترى</small><b>${fmt(r.upsell.orders)}</b></div><div class="stat"><small>وحدات من الاقتراحات</small><b>${fmt(r.upsell.units)}</b></div><div class="stat"><small>قيمة أصناف اقتراحات</small><b>${fmt(r.upsell.revenue)} ج</b></div></div>
<div class="box"><div class="box-header"><h3>⭐ الأصناف المضافة من «كمّل وجبتك»</h3><button class="btn small" data-analytics-refresh>↻ تحديث التحليل</button></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>الطلبات</th><th>الكمية</th><th>قيمة المبيعات</th></tr></thead><tbody>${r.suggestions.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.orders)}</td><td>${fmt(x.units)}</td><td>${fmt(x.revenue)} ج</td></tr>`).join('')||'<tr><td colspan="4">لا توجد مشتريات مسجلة من الاقتراحات حتى الآن</td></tr>'}</tbody></table></div></div>
<div class="grid2"><div class="box"><h3>🔗 أي صنف أدى لاقتراح أي صنف؟</h3><div class="table-wrap"><table><thead><tr><th>مصدر الاقتراح</th><th>الصنف المضاف</th><th>طلبات</th><th>القيمة</th></tr></thead><tbody>${r.sources.map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(x.product)}</td><td>${fmt(x.orders)}</td><td>${fmt(x.revenue)} ج</td></tr>`).join('')||'<tr><td colspan="4">بانتظار طلبات من V5</td></tr>'}</tbody></table></div></div><div class="box"><h3>🛍 الأصناف التي تُطلب مع بعضها</h3><div class="table-wrap"><table><thead><tr><th>الزوج</th><th>عدد الطلبات</th></tr></thead><tbody>${r.pairs.map(x=>`<tr><td>${esc(x.products.join(' + '))}</td><td>${fmt(x.orders)}</td></tr>`).join('')||'<tr><td colspan="2">لا يوجد طلبات مكتملة</td></tr>'}</tbody></table></div></div></div>`;};
const renderBackups=()=>`<div class="panel-note">💾 كل نسخة تحفظ الأصناف والأسعار وإعدادات الموقع والطلبات والكوبونات والجداول وصور الرفع. لا تشمل كلمات مرور حسابات الموظفين. النسخ المحلية محفوظة في DATA_DIR/backups على نفس قرص الاستضافة ويُحتفظ بآخر 10 نسخ، مع محاولة أخذ نسخة عند التشغيل وكل 6 ساعات. <b>حمّل نسخة على جهازك أو خزّنها خارج الاستضافة لحماية بياناتك من تعطل القرص أو حذف الخدمة.</b></div>
<div class="grid2"><div class="box"><h3>حفظ نسخة جديدة</h3><p class="note">يمكنك تحميل نسخ JSON واسترجاعها في نفس الموقع عند الحاجة.</p><button class="btn primary" data-backup-create>+ أخذ نسخة احتياطية الآن</button><hr class="sep"><h3>استيراد نسخة من جهازك</h3><label class="field"><span>ملف نسخة احتياطية (.json) أصلي من V5</span><input type="file" id="backupUpload" accept=".json,application/json"></label><button class="btn danger" data-backup-import>استرجاع الملف (يستبدل البيانات الحالية)</button></div><div class="box"><div class="box-header"><h3>النسخ المحفوظة (${backups.length})</h3><button class="btn small" data-backups-refresh>↻ تحديث</button></div>${backups.map(b=>`<div class="entry"><div><strong>${esc(b.name)}</strong><small>${fmt((b.size/1024/1024).toFixed(2))} ميجابايت</small></div><div class="actions"><a class="btn small" href="/api/admin/backups/download?name=${encodeURIComponent(b.name)}">↓ تحميل</a><button class="btn small danger" data-backup-restore="${esc(b.name)}">استرجاع</button></div></div>`).join('')||'<div class="empty">لم يتم إنشاء نسخ احتياطية بعد</div>'}</div></div>`;
async function refreshBackups(){backups=(await api('/api/admin/backups')).backups;render();}
async function refreshSchedules(){schedules=(await api('/api/admin/pricing-schedules')).schedules;render();}
function scheduleModal(i=null){if(dirty)return showError(Error('احفظ تغييرات المنيو أولاً قبل تعديل الجداول'));
 const x=i===null?{id:uid(),scope:'product',target:'',variant:'',type:'percent_off',value:10,startAt:cairoNow(),endAt:'',enabled:true}:schedules[i];
 const options=(type,value)=>type==='product'?secItems().map(z=>`<option value="${esc(z.item.name)}" ${z.item.name===value?'selected':''}>${esc(z.item.name)}</option>`).join(''):menu.sections.map(z=>`<option value="${esc(z.name)}" ${z.name===value?'selected':''}>${esc(z.name)}</option>`).join('');
 modal(`<h2>${i===null?'إضافة جدول':'تعديل جدول'} أسعار</h2><form id="scheduleForm"><label class="field"><span>نطاق الجدول</span><select id="scScope"><option value="product" ${x.scope==='product'?'selected':''}>صنف</option><option value="section" ${x.scope==='section'?'selected':''}>قسم كامل</option></select></label><label class="field"><span>الصنف أو القسم</span><select id="scTarget"><option value="">اختر</option>${options(x.scope,x.target)}</select></label><label class="field"><span>نوع التغيير</span><select id="scType"><option value="percent_off" ${x.type==='percent_off'?'selected':''}>خصم بالنسبة (%)</option><option value="amount_off" ${x.type==='amount_off'?'selected':''}>خصم مبلغ ثابت (ج)</option><option value="price" ${x.type==='price'?'selected':''}>سعر ثابت للصنف / الحجم (ج)</option></select></label><label class="field"><span>الحجم (عند تحديد سعر ثابت لصنف ذي أحجام)</span><select id="scVariant"><option value="">السعر الأساسي</option></select></label>${field('scValue','النسبة / القيمة',x.value,'number')}<div class="grid2">${field('scStart','البداية بتوقيت القاهرة',x.startAt,'datetime-local')}${field('scEnd','النهاية بتوقيت القاهرة',x.endAt,'datetime-local')}</div><label class="check"><input id="scEnabled" type="checkbox" ${x.enabled?'checked':''}>مفعّل</label><div class="modal-tools"><button class="btn ghost" type="button" data-close>إلغاء</button><button class="btn primary">حفظ الجدول</button></div></form>`);
 const scope=$('#scScope'),target=$('#scTarget'),variant=$('#scVariant'),type=$('#scType');
 const refreshVariants=(keep='')=>{const it=secItems().find(z=>z.item.name===target.value)?.item;variant.innerHTML='<option value="">السعر الأساسي</option>'+Object.keys(it?.variants||{}).map(k=>`<option value="${esc(k)}" ${k===keep?'selected':''}>${esc(k)}</option>`).join('');variant.disabled=scope.value!=='product'||type.value!=='price';};
 scope.onchange=()=>{target.innerHTML='<option value="">اختر</option>'+options(scope.value,'');refreshVariants();};
 target.onchange=()=>refreshVariants();type.onchange=()=>refreshVariants();refreshVariants(x.variant||'');
 $('#scheduleForm').onsubmit=async e=>{e.preventDefault();const entry={id:x.id,scope:scope.value,target:target.value,variant:type.value==='price'&&scope.value==='product'?variant.value:'',type:type.value,value:Number($('#scValue').value),startAt:$('#scStart').value,endAt:$('#scEnd').value,enabled:$('#scEnabled').checked};
 const previous=[...schedules];try{if(!entry.target||!entry.startAt||!entry.endAt||!Number.isFinite(entry.value))throw Error('اختر الصنف وحدد القيمة والمواعيد');if(i===null)schedules.push(entry);else schedules[i]=entry;await api('/api/admin/pricing-schedules',{method:'PUT',body:JSON.stringify({schedules})});hideModal();await refreshSchedules();notice('تم حفظ جدول الأسعار');}catch(err){schedules=previous;showError(err);}};
}

const render=()=>{if(!menu)return;const pages={overview:renderOverview,sections:renderSections,products:renderProducts,recommendations:renderRecommendations,orders:renderOrders,settings,extras:renderExtras,promotions:renderPromotions,hours:renderHours,reports:renderReports,customers:renderCustomers,users:renderUsers,appearance:renderAppearance,pricing:renderPricing,bulk:renderBulk,analytics:renderBasketAnalytics,backups:renderBackups};$('#content').innerHTML=(pages[active]||renderOrders)();};
const modal=(html)=>{$('#modalRoot').innerHTML=`<div class="modal-bg" id="dialogBg"><div class="modal" role="dialog" aria-modal="true" aria-label="تعديل">${html}</div></div>`;};
const hideModal=()=>$('#modalRoot').innerHTML='';
const sectionModal=i=>{const s=i===null?{name:'',description:'',layout:'grid',image:''}:menu.sections[i];modal(`<h2>${i===null?'إضافة قسم':'تعديل القسم'}</h2><form id="sectionForm">${field('secName','اسم القسم',s.name)}${field('secDesc','الوصف (اختياري)',s.description)}${field('secImage','رابط صورة القسم (اختياري)',s.image)}<label class="check"><input id="secDisabled" type="checkbox" ${s.disabled?'checked':''}>إيقاف جميع أصناف القسم مؤقتاً</label><label class="check"><input id="secHidden" type="checkbox" ${s.hidden?'checked':''}>إخفاء القسم من المنيو</label><label class="field"><span>طريقة العرض</span><select id="secLayout"><option value="grid" ${s.layout==='grid'?'selected':''}>شبكة</option><option value="carousel" ${s.layout==='carousel'?'selected':''}>سلايدر</option><option value="list" ${s.layout==='list'?'selected':''}>قائمة</option></select></label><div class="modal-tools"><button class="btn ghost" type="button" data-close>إلغاء</button><button class="btn primary" type="submit">تطبيق التعديل</button></div></form>`);$('#sectionForm').onsubmit=e=>{e.preventDefault();const name=$('#secName').value.trim();if(!name)return showError(Error('اكتب اسم القسم'));const obj={...s,name,description:$('#secDesc').value.trim(),image:$('#secImage').value.trim(),layout:$('#secLayout').value,disabled:$('#secDisabled').checked,hidden:$('#secHidden').checked,items:s.items||[],id:s.id||uid()};if(i===null)menu.sections.push(obj);else menu.sections[i]=obj;hideModal();changed();};};
const productModal=(si=null,ii=null)=>{
 if(!menu.sections.length)return showError(Error('أضف قسمًا أولًا'));
 const old=ii===null?{name:'',description:'',price:0,from:false,off:false,image:''}:menu.sections[si].items[ii];
 modal(`<h2>${ii===null?'إضافة صنف جديد':'تعديل الصنف'}</h2><form id="productForm"><label class="field"><span>القسم</span><select id="productCat">${menu.sections.map((s,i)=>`<option value="${i}" ${si===i?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${field('productName','اسم الصنف',old.name)}${field('productPrice','السعر بالجنيه',old.price,'number')}<label class="field"><span>الوصف</span><textarea id="productDesc">${esc(old.description||'')}</textarea></label>${field('productImage','رابط الصورة',old.image||'')}<label class="field"><span>أسعار الأوزان/الأحجام (اختياري: كل سطر «الوزن | السعر»)</span><textarea id="productVariants" placeholder="نص كيلو | 250">${esc(Object.entries(old.variants||{}).map(([k,v])=>`${k} | ${v}`).join('\n'))}</textarea></label><label class="field"><span>رفع صورة من الجهاز (حتى 4 ميجابايت)</span><input id="productFile" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="uploadStatus" class="file-preview"></div><label class="check"><input id="productFrom" type="checkbox" ${old.from?'checked':''}> السعر يبدأ من</label><label class="check"><input id="productOff" type="checkbox" ${old.off?'checked':''}> نفد مؤقتاً</label><label class="check"><input id="productHidden" type="checkbox" ${old.hidden?'checked':''}> إخفاء الصنف من المنيو</label><div class="box"><h3>مجموعات الإضافات المرتبطة بالصنف</h3>${(getSettings().addonGroups||[]).map(g=>`<label class="check"><input type="checkbox" data-item-group="${esc(g.id)}" ${(old.addonGroups||[]).includes(g.id)?'checked':''}>${esc(g.name)} ${g.required?'(إجباري)':'(اختياري)'}</label>`).join('')||'<p class="note">أضف مجموعات من تبويب الإضافات والأحجام</p>'}</div><div class="modal-tools"><button class="btn ghost" type="button" data-close>إلغاء</button><button class="btn primary" id="productSubmit" type="submit">تطبيق التعديل</button></div></form>`);
 $('#productForm').onsubmit=async(e)=>{e.preventDefault();const b=$('#productSubmit');b.disabled=true;try{
  const name=$('#productName').value.trim(),price=Number($('#productPrice').value),cat=Number($('#productCat').value);
  if(!name||!Number.isFinite(price)||price<0)throw Error('ادخل اسم وسعر صالحين');
  if(secItems().some(x=>x.item.name===name&&!(si===x.si&&ii===x.ii)))throw Error('اسم الصنف موجود بالفعل، استخدم اسمًا مختلفًا');
  let image=$('#productImage').value.trim(),file=$('#productFile').files[0];
  if(file){if(file.size>4_000_000)throw Error('الصورة أكبر من 4 ميجابايت');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('صيغة الصورة غير مدعومة');$('#uploadStatus').textContent='جاري رفع الصورة...';const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذّر قراءة الصورة'));r.readAsDataURL(file);});const response=await api('/api/admin/upload',{method:'POST',body:JSON.stringify({data})});image=response.url;}
  if(image&&!/^(https?:\/\/|\/assets\/)/i.test(image))throw Error('اكتب رابط صورة يبدأ بـ https:// أو ارفعها من جهازك');
  const lines=$('#productVariants').value.split(/\n/).map(x=>x.trim()).filter(Boolean),variants={};
  for(const row of lines){const parts=row.split('|').map(x=>x.trim());if(parts.length!==2||!parts[0]||!Number.isFinite(Number(parts[1]))||Number(parts[1])<0)throw Error('راجع أسعار الأوزان: '+row);variants[parts[0]]=Number(parts[1]);}
  const obj={...old,name,price,image,description:$('#productDesc').value.trim(),from:$('#productFrom').checked,off:$('#productOff').checked,hidden:$('#productHidden').checked,addonGroups:[...document.querySelectorAll('[data-item-group]:checked')].map(x=>x.dataset.itemGroup)};
  if(lines.length)obj.variants=variants;else delete obj.variants;
  if(ii!==null){renameRecommendation(old.name,name);menu.sections[si].items.splice(ii,1);}menu.sections[cat].items.push(obj);
  hideModal();changed();notice('تم تطبيق التعديل. اضغط حفظ لنشره.');
 }catch(err){showError(err);b.disabled=false;}};
};
async function loadImages(){try{imageStatus=await api('/api/admin/images');if(active==='overview')render();}catch(e){imageStatus=null;}}
function chime(){if(!soundEnabled)return;try{const ac=new (window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),v=ac.createGain();o.connect(v);v.connect(ac.destination);o.type='sine';o.frequency.setValueAtTime(900,ac.currentTime);o.frequency.setValueAtTime(1180,ac.currentTime+.12);v.gain.setValueAtTime(.08,ac.currentTime);v.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.28);o.start();o.stop(ac.currentTime+.3);setTimeout(()=>ac.close(),500);}catch(e){}}
async function loadOrders(silent=false){try{const next=(await api('/api/admin/orders')).orders||[];const ids=new Set(next.map(o=>o.id));if(seenOrderIds&&next.some(o=>o.status==='new'&&!seenOrderIds.has(o.id))){chime();if(silent)notice('🔔 وصل طلب جديد');}seenOrderIds=ids;orders=next;if(active==='orders'||active==='overview'||active==='customers')render();}catch(e){if(!silent)showError(e);}}
async function loadMenu(){menu=await api(role==='admin'?'/api/admin/menu':'/api/menu');menu.sections=Array.isArray(menu.sections)?menu.sections:[];menu.contact=menu.contact||{};original=JSON.stringify(menu);setDirty(false);await loadOrders();if(role==='admin')await loadImages();await loadExtras();view(role==='staff'?'orders':active);}
async function save(){if(!dirty)return notice('لا توجد تغييرات جديدة');try{const buttons=['#saveTop','#saveBanner','#saveMobile'].map(x=>$(x));buttons.forEach(x=>x.disabled=true);await api('/api/admin/menu',{method:'PUT',body:JSON.stringify(menu)});original=JSON.stringify(menu);setDirty(false);notice('✓ تم نشر التعديلات بنجاح');}catch(e){showError(e);}finally{['#saveTop','#saveBanner','#saveMobile'].forEach(x=>$(x).disabled=false);}}
function authScreen(yes){$('#auth').classList.toggle('hidden',yes);$('#app').classList.toggle('hidden',!yes);}
async function start(){try{const s=await api('/api/admin/session');if(s.authenticated){role=s.role;username=s.username;authScreen(true);await loadMenu();}else authScreen(false);}catch(e){showError(e);authScreen(false);}}
$('#authForm').addEventListener('submit',async(e)=>{e.preventDefault();$('#authError').textContent='';try{const b=$('#authSubmit');b.disabled=true;await api('/api/admin/login',{method:'POST',body:JSON.stringify({username:$('#authUser').value,password:$('#authPass').value})});$('#authPass').value='';const current=await api('/api/admin/session');role=current.role;username=current.username;authScreen(true);await loadMenu();}catch(err){$('#authError').textContent=err.message;}finally{$('#authSubmit').disabled=false;}});
$('#signout').addEventListener('click',async()=>{if(!confirmDirty())return;try{await api('/api/admin/logout',{method:'POST',body:'{}'});}catch(e){showError(e);}menu=null;orders=[];seenOrderIds=null;setDirty(false);authScreen(false);});
for(const id of ['#saveTop','#saveBanner','#saveMobile'])$(id).addEventListener('click',save);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
$('#content').addEventListener('input',e=>{if(e.target.id==='recoSearch'){const pos=e.target.selectionStart;recoQuery=e.target.value;render();const f=$('#recoSearch');f.focus();f.setSelectionRange(pos,pos);return;}if(e.target.id==='orderSearch'){const pos=e.target.selectionStart;orderQuery=e.target.value;render();const el=$('#orderSearch');el.focus();el.setSelectionRange(pos,pos);return;}if(e.target.id==='findItems'){const pos=e.target.selectionStart;q=e.target.value;render();const f=$('#findItems');f.focus();f.setSelectionRange(pos,pos);}});
$('#content').addEventListener('change',async e=>{
 if(e.target.id==='smartProduct'){smartProduct=e.target.value;render();}
 if(e.target.id==='catFilter'){selectedCat=e.target.value;render();}
 if(e.target.id==='bulkScope'){bulkFilter=e.target.value;render();}
 if(e.target.hasAttribute('data-bulk-item')){if(e.target.checked)bulkSelected.add(e.target.dataset.bulkItem);else bulkSelected.delete(e.target.dataset.bulkItem);}
 if(e.target.id==='offersEnabled'){recoSettings().offersEnabled=e.target.checked;changed();}
 if(e.target.id==='upsellEnabled'){recoSettings().upsell.enabled=e.target.checked;changed();}
 if(e.target.id==='upsellLimit'){recoSettings().upsell.limit=Number(e.target.value);changed();}
 if(e.target.id==='offersTitle'){recoSettings().offersTitle=e.target.value.trim()||'العروض';changed();}
 if(e.target.matches('[data-order-status]')){const id=e.target.dataset.orderStatus,old=orders.find(o=>o.id===id);try{await api('/api/admin/orders/'+id,{method:'PATCH',body:JSON.stringify({status:e.target.value})});if(old)old.status=e.target.value;notice('تم تحديث حالة الطلب');}catch(err){if(old)e.target.value=old.status;showError(err);}}
});
document.addEventListener('click',async e=>{
 const target=e.target.closest('button,[data-tab]');if(!target)return;
 if(target.hasAttribute('data-close')){hideModal();return;}
 if(target.hasAttribute('data-schedule-edit'))return scheduleModal(target.dataset.scheduleEdit==='new'?null:Number(target.dataset.scheduleEdit));
 if(target.hasAttribute('data-schedule-refresh')){try{await refreshSchedules();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-schedule-delete')){if(dirty)return showError(Error('احفظ المنيو أولاً'));if(!confirm('حذف جدول الأسعار؟'))return;const old=[...schedules];schedules.splice(+target.dataset.scheduleDelete,1);try{await api('/api/admin/pricing-schedules',{method:'PUT',body:JSON.stringify({schedules})});await refreshSchedules();}catch(err){schedules=old;showError(err);}return;}
 if(target.hasAttribute('data-bulk-select')){document.querySelectorAll('[data-bulk-item]').forEach(el=>{el.checked=true;bulkSelected.add(el.dataset.bulkItem);});render();return;}
 if(target.hasAttribute('data-bulk-clear')){bulkSelected.clear();render();return;}
 if(target.hasAttribute('data-bulk-apply')){if(dirty)return showError(Error('احفظ تعديلات المنيو الحالية أولاً'));const section=$('#bulkScope').value,items=[...bulkSelected],action=$('#bulkAction').value,percent=Number($('#bulkPercent').value),state=$('#bulkState').value;if(!items.length&&!section)return showError(Error('اختار قسماً أو أصنافاً'));const what=items.length?items.length+' صنفاً':`كل أصناف «${section}»`;if(!confirm(`تأكيد ${action==='raise_percent'?'تغيير الأسعار '+percent+'%':'تغيير حالة التوفر إلى '+state} لـ ${what}؟ سيتم الحفظ فوراً.`))return;try{const result=await api('/api/admin/bulk',{method:'POST',body:JSON.stringify({section,items,action,percent,state})});menu=await api('/api/admin/menu');setDirty(false);bulkSelected.clear();render();notice('تم تحديث '+result.changed+' صنفاً على السيرفر');}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-analytics-refresh')){try{basketReport=await api('/api/admin/basket-analytics');render();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-backup-create')){try{const b=await api('/api/admin/backups',{method:'POST',body:'{}'});await refreshBackups();notice('تم إنشاء نسخة '+b.name);}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-backups-refresh')){try{await refreshBackups();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-backup-restore')||target.hasAttribute('data-backup-import')){
   if(dirty)return showError(Error('احفظ أو تراجع عن تغييرات المنيو أولاً'));
   const importing=target.hasAttribute('data-backup-import'),name=target.dataset.backupRestore;let backup;
   if(importing){const file=$('#backupUpload')?.files?.[0];if(!file)return showError(Error('اختر ملف نسخة'));if(file.size>45_000_000)return showError(Error('حجم الملف كبير'));try{backup=JSON.parse(await file.text());}catch(err){return showError(Error('ملف JSON غير صالح'));}}
   if(!confirm('تحذير: الاسترجاع يستبدل الطلبات والأصناف والعروض الحالية. سيتم أخذ نسخة أمان أولاً. هل تريد المتابعة؟'))return;
   if(prompt('اكتب كلمة استرجاع للتأكيد النهائي')!=='استرجاع')return;
   try{const result=await api('/api/admin/backups/restore',{method:'POST',body:JSON.stringify({confirm:'RESTORE',...(importing?{backup}:{name})})});notice('تم الاسترجاع! نسخة الأمان: '+result.safetyBackup);bulkSelected.clear();await loadMenu();}catch(err){showError(err);}return;
 }

 if(target.hasAttribute('data-tab')){const t=target.dataset.tab;if(t==='orders')await loadOrders();view(t);return;}
 if(target.hasAttribute('data-add-section'))return sectionModal(null);
 if(target.hasAttribute('data-edit-section'))return sectionModal(+target.dataset.editSection);
 if(target.hasAttribute('data-go-section')){selectedCat=target.dataset.goSection;view('products');return;}
 if(target.hasAttribute('data-toggle-section')){const s=menu.sections[+target.dataset.toggleSection];s.disabled=!s.disabled;changed();return;}
 if(target.hasAttribute('data-hide-section')){const s=menu.sections[+target.dataset.hideSection];s.hidden=!s.hidden;changed();return;}
 if(target.hasAttribute('data-del-section')){const i=+target.dataset.delSection,s=menu.sections[i];if(s.items.length&&!confirm(`القسم «${s.name}» يحتوي ${s.items.length} صنفًا. هل تريد حذف القسم وكل أصنافه؟`))return;if(!s.items.length&&!confirm(`حذف القسم «${s.name}»؟`))return;s.items.forEach(it=>removeRecommendation(it.name));menu.sections.splice(i,1);selectedCat='';changed();return;}
 if(target.hasAttribute('data-move-section')){const i=+target.dataset.moveSection,j=i+Number(target.dataset.step);if(j<0||j>=menu.sections.length)return;[menu.sections[i],menu.sections[j]]=[menu.sections[j],menu.sections[i]];changed();return;}
 if(target.hasAttribute('data-add-item'))return productModal(null,null);
 if(target.hasAttribute('data-edit-item')){const [si,ii]=target.dataset.editItem.split(':').map(Number);return productModal(si,ii);}
 if(target.hasAttribute('data-toggle-item')){const [si,ii]=target.dataset.toggleItem.split(':').map(Number);menu.sections[si].items[ii].off=!menu.sections[si].items[ii].off;changed();return;}
 if(target.hasAttribute('data-hide-item')){const [si,ii]=target.dataset.hideItem.split(':').map(Number);menu.sections[si].items[ii].hidden=!menu.sections[si].items[ii].hidden;changed();return;}
 if(target.hasAttribute('data-del-item')){const [si,ii]=target.dataset.delItem.split(':').map(Number);if(!confirm(`حذف «${menu.sections[si].items[ii].name}»؟`))return;removeRecommendation(menu.sections[si].items[ii].name);menu.sections[si].items.splice(ii,1);changed();return;}
 if(target.hasAttribute('data-sync-images')){try{await api('/api/admin/images/sync',{method:'POST',body:'{}'});await loadImages();notice('جاري محاولة جلب الصور الأصلية وحفظها على الاستضافة');}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-smart-add')){const name=$('#smartSuggestion')?.value;if(!smartProduct||!name)return;const list=recoSettings().upsell.byProduct[smartProduct]||[];if(list.length>=40)return showError(Error('الحد 40 صنفاً'));recoSettings().upsell.byProduct[smartProduct]=[...list,name];changed();return;}
 if(target.hasAttribute('data-smart-remove')){const arr=recoSettings().upsell.byProduct[smartProduct]||[];arr.splice(+target.dataset.smartRemove,1);if(!arr.length)delete recoSettings().upsell.byProduct[smartProduct];changed();return;}
 if(target.hasAttribute('data-smart-move')){const arr=recoSettings().upsell.byProduct[smartProduct]||[],i=+target.dataset.smartMove,j=i+Number(target.dataset.step);if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];changed();return;}
 if(target.hasAttribute('data-rec-add')){
  const kind=target.dataset.recAdd,name=target.dataset.name,item=secItems().find(x=>x.item.name===name)?.item;
  if(!['offers','upsell'].includes(kind)||!item)return;
  const items=recoList(kind);if(items.some(x=>recoName(x)===name))return;
  if(items.length>=40)return showError(Error('الحد الأقصى 40 صنفاً للقسم'));
  items.push(name);changed();notice('تمت إضافة الصنف. اضغط حفظ لنشر التعديل.');return;
 }
 if(target.hasAttribute('data-rec-remove')){
  const [kind,position]=target.dataset.recRemove.split(':'),list=recoList(kind),i=Number(position);
  if(!Number.isInteger(i)||i<0||i>=list.length)return;list.splice(i,1);changed();return;
 }
 if(target.hasAttribute('data-rec-move')){
  const [kind,position]=target.dataset.recMove.split(':'),list=recoList(kind),i=Number(position),j=i+Number(target.dataset.step);
  if(!Number.isInteger(i)||!Number.isInteger(j)||i<0||j<0||i>=list.length||j>=list.length)return;
  [list[i],list[j]]=[list[j],list[i]];changed();return;
 }
 if(target.hasAttribute('data-sound')){soundEnabled=!soundEnabled;if(soundEnabled)chime();render();return;}
 if(target.hasAttribute('data-refresh-orders'))return loadOrders();
 if(target.hasAttribute('data-export-orders')){const blob=new Blob([JSON.stringify(orders,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='halab_orders_'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);return;}
 if(target.hasAttribute('data-group-edit'))return groupModal(target.dataset.groupEdit==='new'?null:Number(target.dataset.groupEdit));
 if(target.hasAttribute('data-group-delete')){const i=Number(target.dataset.groupDelete),g=groupList()[i];if(!confirm('حذف المجموعة '+g.name+' وفصلها عن جميع الأصناف؟'))return;for(const x of secItems())x.item.addonGroups=(x.item.addonGroups||[]).filter(id=>id!==g.id);groupList().splice(i,1);changed();return;}
 if(target.hasAttribute('data-coupon-edit'))return couponModal(target.dataset.couponEdit==='new'?null:Number(target.dataset.couponEdit));
 if(target.hasAttribute('data-bundle-edit'))return bundleModal(target.dataset.bundleEdit==='new'?null:Number(target.dataset.bundleEdit));
 if(target.hasAttribute('data-coupon-delete')||target.hasAttribute('data-bundle-delete')){if(!confirm('حذف العرض أو الكوبون؟'))return;const coupons=target.hasAttribute('data-coupon-delete'),arr=coupons?promotions.coupons:promotions.bundles,old=[...arr];arr.splice(Number(coupons?target.dataset.couponDelete:target.dataset.bundleDelete),1);try{await savePromotions();}catch(err){if(coupons)promotions.coupons=old;else promotions.bundles=old;showError(err);}return;}
 if(target.hasAttribute('data-user-add'))return userModal(null);
 if(target.hasAttribute('data-user-edit'))return userModal(target.dataset.userEdit);
 if(target.hasAttribute('data-user-delete')){if(!confirm('حذف المستخدم نهائياً؟'))return;try{await api('/api/admin/users/'+target.dataset.userDelete,{method:'DELETE'});users=(await api('/api/admin/users')).users;render();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-refresh-reports')){try{report=await api('/api/admin/report');render();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-export-sales')){window.location.href='/api/admin/report.xlsx';return;}
 if(target.hasAttribute('data-save-hours')){const days={};for(let i=0;i<7;i++)if(document.querySelector(`[data-workday="${i}"]`).checked)days[i]={open:document.querySelector(`[data-open="${i}"]`).value,close:document.querySelector(`[data-close="${i}"]`).value};const s=getSettings();s.schedule={enabled:$('#scheduleOn').checked,days};changed();return;}
 if(target.hasAttribute('data-save-delivery')){try{const zones=parsePriceRows($('#workZones').value).map(x=>({name:x.name,fee:x.price}));if(new Set(zones.map(x=>x.name)).size!==zones.length)throw Error('أسماء المناطق مكررة');const s=getSettings();s.zones=zones;s.freeDeliveryThreshold=Math.max(0,Number($('#workFree').value)||0);s.minimumOrder=Math.max(0,Number($('#minimumOrder').value)||0);changed();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-save-banners')){try{const lines=$('#bannersText').value.split(/\n/).map(x=>x.trim()).filter(Boolean);const b=lines.map(line=>{const idx=line.indexOf('|');if(idx<1)throw Error('صيغة البانر يجب عنوان | رابط الصورة');return {title:line.slice(0,idx).trim(),image:line.slice(idx+1).trim()};});if(b.some(x=>!x.title||!(/^(https:\/\/|\/assets\/)/.test(x.image))))throw Error('رابط بانر غير صالح');getSettings().banners=b;changed();}catch(err){showError(err);}return;}
 if(target.hasAttribute('data-save-zones')){try{const lines=$('#zonesText').value.split(/\n/).map(x=>x.trim()).filter(Boolean);const zones=lines.map(x=>{const parts=x.split('|').map(v=>v.trim());const fee=Number(parts[1]);if(parts.length!==2||!parts[0]||!Number.isFinite(fee)||fee<0)throw Error('صيغة المنطقة غير صحيحة: '+x);return {name:parts[0],fee};});const s=getSettings();s.zones=zones;s.freeDeliveryThreshold=Math.max(0,Number($('#setFree').value)||0);changed();notice('تم تطبيق المناطق؛ اضغط حفظ للنشر');}catch(err){showError(err);}return;}
});
$('#content').addEventListener('submit',e=>{if(e.target.id==='appearanceForm'){e.preventDefault();(async()=>{try{const t=getSettings().theme||{};const primary=$('#stylePrimary').value.trim(),accent=$('#styleAccent').value.trim();if(!/^#[0-9a-f]{6}$/i.test(primary)||!/^#[0-9a-f]{6}$/i.test(accent))throw Error('اكتب الألوان بالشكل #aabbcc');t.title=$('#styleTitle').value.trim();t.primary=primary;t.accent=accent;getSettings().theme=t;getSettings().heroSubtitle=$('#styleSub').value.trim();menu.logo=(await uploadFile($('#styleLogoFile').files[0]))||$('#styleLogo').value.trim();menu.cover=(await uploadFile($('#styleCoverFile').files[0]))||$('#styleCover').value.trim();changed();}catch(err){showError(err);}})();return;}if(e.target.id!=='settingsForm')return;e.preventDefault();const c=menu.contact;menu.name=$('#setName').value.trim();c.phone=$('#setPhone').value.trim();c.whatsapp=$('#setWhats').value.trim();c.facebook=$('#setFacebook').value.trim();c.orders=$('#setOrders').checked;menu.logo=$('#setLogo').value.trim();menu.cover=$('#setCover').value.trim();const s=getSettings();s.hotline=$('#setHotline').value.trim();s.heroSubtitle=$('#setSubtitle').value.trim();if(!menu.name)return showError(Error('اسم المطعم مطلوب'));changed();notice('تم تطبيق البيانات؛ اضغط حفظ للنشر');});
setInterval(()=>{if(menu&&role==='admin'&&active==='overview')loadImages();},20000);
setInterval(()=>{if(menu)loadOrders(true);},7000);
document.addEventListener('error',e=>{
 const img=e.target;if(!(img instanceof HTMLImageElement)||img.dataset.fallbackApplied)return;
 img.dataset.fallbackApplied='1';img.src='/assets/product-placeholder.webp';
},true);
start();
})();
